/**
 * @description Payload Source Apex Class: creates the event's Payload Class (it must implement
 * IntegrationHub.IPayloadBuilder), calls build once for the whole batch and turns each record's result into a body.
 * A Map gets the Transaction Id Key added and is serialized; a String is sent as is; nothing fails permanently.
 * request and apply need no records, so they can be tested without data.
 * @group Integration Hub
 */
public with sharing class IntegrationHubPayloadClass {

    /**
     * @description Builds the bodies of one event's transactions with its payload class.
     * @param ev the event (Event_Key__c, Related_Object__c, Payload_Class__c, Transaction_Id_Key__c)
     * @param txns the transactions
     * @return the bodies and errors
     */
    public static IntegrationHubPayload.Result build(IH_Event__c ev, List<IH_Transaction__c> txns) {
        Map<Id, Object> results = new Map<Id, Object>();
        String problem;
        try {
            results = newBuilder(ev.Payload_Class__c).build(request(ev, txns));
        } catch (Exception e) {
            problem = 'Payload class ' + ev.Payload_Class__c + ' failed: ' + e.getMessage();
        }
        return problem == null ? apply(results, txns, IntegrationHubPayload.txnKeyOf(ev)) : failAll(txns, problem);
    }

    /**
     * @description The request handed to the payload class: every record Id of the batch, once.
     * @param ev the event
     * @param txns the transactions
     * @return the request
     */
    public static IntegrationHub.PayloadRequest request(IH_Event__c ev, List<IH_Transaction__c> txns) {
        IntegrationHub.PayloadRequest req = new IntegrationHub.PayloadRequest();
        req.eventKey = ev.Event_Key__c;
        req.relatedObject = String.isBlank(ev.Related_Object__c) && !txns.isEmpty() ? txns[0].Related_Object__c : ev.Related_Object__c;
        for (IH_Transaction__c t : txns) {
            Id recordId = (Id) t.Related_Record_Id__c;
            if (!req.transactionIdByRecordId.containsKey(recordId)) {
                req.recordIds.add(recordId);
            }
            req.transactionIdByRecordId.put(recordId, t.Id);
        }
        return req;
    }

    /**
     * @description Creates the payload class.
     * @param className the Payload Class
     * @return the builder
     * @throws IntegrationHub.HubException when the class is missing or does not implement IntegrationHub.IPayloadBuilder
     */
    public static IntegrationHub.IPayloadBuilder newBuilder(String className) {
        Object created = IntegrationHub.createInstance(className);
        if (!(created instanceof IntegrationHub.IPayloadBuilder)) {
            throw new IntegrationHub.HubException(className + ' does not implement IntegrationHub.IPayloadBuilder');
        }
        return (IntegrationHub.IPayloadBuilder) created;
    }

    /**
     * @description Turns the class results into bodies, per transaction.
     * @param results the class result per record Id (may be null)
     * @param txns the transactions
     * @param txnKey the JSON key of the transaction Id
     * @return the bodies and errors
     */
    public static IntegrationHubPayload.Result apply(Map<Id, Object> results, List<IH_Transaction__c> txns, String txnKey) {
        IntegrationHubPayload.Result result = new IntegrationHubPayload.Result();
        Map<Id, Object> safe = results == null ? new Map<Id, Object>() : results;
        for (IH_Transaction__c t : txns) {
            String body = bodyOf(safe.get((Id) t.Related_Record_Id__c), txnKey, t.Id);
            if (body == null) {
                result.errors.put(t.Id, 'Payload class returned nothing for record ' + t.Related_Record_Id__c);
            } else {
                result.bodies.put(t.Id, body);
            }
        }
        return result;
    }

    /**
     * @description Fails every transaction with the same problem (class missing, wrong interface, threw).
     * @param txns the transactions
     * @param problem the problem
     * @return the errors
     */
    public static IntegrationHubPayload.Result failAll(List<IH_Transaction__c> txns, String problem) {
        IntegrationHubPayload.Result result = new IntegrationHubPayload.Result();
        for (IH_Transaction__c t : txns) {
            result.errors.put(t.Id, problem);
        }
        return result;
    }

    private static String bodyOf(Object value, String txnKey, Id transactionId) {
        if (value instanceof String) {
            return String.isBlank((String) value) ? null : (String) value;
        }
        if (value instanceof Map<String, Object>) {
            Map<String, Object> body = new Map<String, Object>((Map<String, Object>) value);
            body.put(txnKey, transactionId);
            return JSON.serialize(body);
        }
        return value == null ? null : JSON.serialize(value);
    }
}
